pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMin, uint256 newMin, uint256 lockTime, uint256 collectAmt) public {
        // Constrain to admissible domain: MinSum > 0 to have meaningful amounts, lockTime reasonable, collectAmt > 0
        vm.assume(initialMin > 0);
        vm.assume(newMin > 0);
        vm.assume(newMin != initialMin);
        vm.assume(lockTime > 0);
        vm.assume(collectAmt > 0);
        vm.assume(collectAmt <= initialMin);

        // Initialize contract
        c.Initialized();
        c.SetMinSum(initialMin);

        // Deploy reentrant attacker that calls SetMinSum during Collect
        ReentrantAttacker attacker = new ReentrantAttacker(address(c), newMin);

        // Fund attacker so it can deposit and trigger Collect
        uint256 depositAmt = initialMin;
        vm.deal(address(attacker), depositAmt);

        // Attacker deposits via Put to set up balance and unlock time
        vm.prank(address(attacker));
        c.Put{value: depositAmt}(lockTime);

        // Warp past unlock time to allow Collect
        vm.warp(block.timestamp + lockTime + 1);

        // Record MinSum before Collect
        uint256 minSumBefore = c.MinSum();

        // Attacker calls Collect, which triggers reentrancy into SetMinSum
        vm.prank(address(attacker));
        attacker.attack(collectAmt);

        // After Collect completes, MinSum must remain unchanged from before the call
        assertTrue(c.MinSum() == minSumBefore);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 newMin;
    bool reentering;

    constructor(address _target, uint256 _newMin) {
        target = C(_target);
        newMin = _newMin;
        reentering = false;
    }

    function attack(uint256 collectAmt) external payable {
        // Mark reentrancy phase
        reentering = true;
        target.Collect(collectAmt);
        reentering = false;
    }

    receive() external payable {
        // During Collect, call SetMinSum to change MinSum reentrantly
        if (reentering) {
            target.SetMinSum(newMin);
        }
    }
}

