contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSumInitial, uint256 reentrantMinSum, uint256 deposit, uint256 collectAmt) public {
        vm.assume(minSumInitial > 0);
        vm.assume(reentrantMinSum != minSumInitial);
        vm.assume(deposit >= collectAmt);
        vm.assume(collectAmt > 0);
        vm.assume(minSumInitial <= deposit);

        c.SetMinSum(minSumInitial);
        c.Initialized();

        ReentrantCollector attacker = new ReentrantCollector(c);
        vm.deal(address(attacker), deposit);
        attacker.prepare{value: deposit}(reentrantMinSum, collectAmt);

        (bool ok,) = address(attacker).call(abi.encodeWithSignature("attack()"));
        ok; // suppress unused variable warning

        uint256 currentMinSum = c.MinSum();
        // The reference will keep MinSum unchanged (minSumInitial) because the lock prevents reentrancy.
        // The buggy version allows the reentrant SetMinSum to succeed, so MinSum becomes reentrantMinSum.
        // General property: MinSum equals either minSumInitial (correct lock) or reentrantMinSum (if reentrancy occurs).
        // The bug breaks any invariant that demands MinSum == minSumInitial, but here we assert the true property
        // that the reference always satisfies: MinSum is either the initial or the reentrant value.
        // However, the buggy one can have MinSum == reentrantMinSum while the correct one never does.
        // To make it a single assertion that passes on reference and fails on bug, we check:
        //   MinSum == minSumInitial   (reference: true, bug: false)
        assertTrue(currentMinSum == minSumInitial);
    }
}

